import io.github.resilience4j.bulkhead.Bulkhead;
import io.github.resilience4j.bulkhead.BulkheadConfig;
import io.github.resilience4j.bulkhead.BulkheadRegistry;
import java.time.Duration;
import java.util.concurrent.CompletableFuture;
import java.util.function.Supplier;

public class BulkheadDemo {
    public static void main(String[] args) {
        BulkheadConfig config = BulkheadConfig.custom()
            .maxConcurrentCalls(15)
            .maxWaitDuration(Duration.ofMillis(200))
            .build();

        BulkheadRegistry registry = BulkheadRegistry.of(config);
        Bulkhead bulkhead = registry.bulkhead("paymentService");

        Supplier<CompletableFuture<String>> restrictedCall = Bulkhead.decorateSupplier(
            bulkhead,
            () -> CompletableFuture.completedFuture("Processed payment successfully")
        );

        restrictedCall.get().thenAccept(System.out::println);
    }
}
